'use client'

import Link from 'next/link'
import { useCallback, useEffect, useState } from 'react'
import type { AdminVendor, VendorListResult, VendorStatus } from '@/lib/admin/vendors'

const statuses: Array<{ value: VendorStatus | ''; label: string }> = [{ value: '', label: 'All statuses' }, { value: 'invited', label: 'Invited' }, { value: 'registered', label: 'Registered' }, { value: 'onboarding', label: 'Onboarding' }, { value: 'active', label: 'Active' }, { value: 'suspended', label: 'Suspended' }, { value: 'inactive', label: 'Inactive' }, { value: 'rejected', label: 'Rejected' }]

function label(value: string) { return value.replaceAll('_', ' ') }
function formatDate(value: string) { return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) }

export function VendorsWorkspace() {
  const [result, setResult] = useState<VendorListResult | null>(null); const [search, setSearch] = useState(''); const [status, setStatus] = useState<VendorStatus | ''>(''); const [sort, setSort] = useState<'updated_desc' | 'name_asc' | 'status_asc'>('updated_desc'); const [page, setPage] = useState(1); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [inviteOpen, setInviteOpen] = useState(false); const [email, setEmail] = useState(''); const [companyName, setCompanyName] = useState(''); const [message, setMessage] = useState('')

  const loadVendors = useCallback(async () => { setLoading(true); try { const params = new URLSearchParams({ search, status, sort, page: String(page), pageSize: '20' }); const response = await fetch(`/api/admin/vendors?${params}`); const data = await response.json() as VendorListResult & { error?: string }; if (!response.ok) throw new Error(data.error || 'Unable to load vendors.'); setResult(data); setError('') } catch (loadError) { setError(loadError instanceof Error ? loadError.message : 'Unable to load vendors.') } finally { setLoading(false) } }, [page, search, sort, status])
  useEffect(() => { void loadVendors() }, [loadVendors])
  async function invite() { const response = await fetch('/api/admin/vendors', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, companyName }) }); const data = await response.json() as { error?: string }; if (!response.ok) { setMessage(data.error || 'Invitation failed.'); return } setInviteOpen(false); setEmail(''); setCompanyName(''); setMessage('Invitation recorded. Email delivery remains a platform integration TODO.'); void loadVendors() }

  return <main className="admin-page"><header className="admin-header"><Link href="/admin" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/admin" className="admin-nav-link">Dashboard</Link><span className="admin-role-chip">Vendor management</span></nav></header><div className="admin-shell"><section className="admin-hero admin-hero-compact"><div><p className="admin-eyebrow">Admin portal / Phase 02</p><h1>Vendor directory.</h1><p>Review the full marketplace network, follow onboarding progress, and manage vendor access without deleting business history.</p></div><button type="button" className="admin-button admin-button-primary" onClick={() => setInviteOpen(true)}>Invite vendor <span aria-hidden="true">+</span></button></section>{message ? <div className="admin-config-notice" role="status">{message}</div> : null}<section className="admin-filter-bar" aria-label="Vendor filters"><label><span>Search vendors</span><input value={search} onChange={(event) => { setPage(1); setSearch(event.target.value) }} placeholder="Name or email" /></label><label><span>Status</span><select value={status} onChange={(event) => { setPage(1); setStatus(event.target.value as VendorStatus | '') }}>{statuses.map((item) => <option value={item.value} key={item.value}>{item.label}</option>)}</select></label><label><span>Sort</span><select value={sort} onChange={(event) => setSort(event.target.value as typeof sort)}><option value="updated_desc">Recently updated</option><option value="name_asc">Name A-Z</option><option value="status_asc">Status</option></select></label></section>{error ? <div className="admin-config-notice admin-config-error" role="alert">{error}</div> : null}<section className="admin-panel admin-vendor-table-panel"><div className="admin-panel-heading"><div><p className="admin-eyebrow">Platform vendors</p><h2>{result ? `${result.total} vendors` : 'Vendor list'}</h2></div><span className="admin-data-note">Server-side pagination</span></div>{loading ? <p className="admin-empty" role="status">Loading vendors...</p> : result?.items.length ? <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Vendor</th><th>Status</th><th>Onboarding</th><th>Products</th><th>Updated</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{result.items.map((vendor) => <VendorRow vendor={vendor} key={vendor.id} />)}</tbody></table></div> : <p className="admin-empty">No vendors match the current filters.</p>}<div className="admin-pagination"><button type="button" className="admin-button admin-button-secondary" disabled={!result || page <= 1} onClick={() => setPage((current) => current - 1)}>Previous</button><span>{result ? `Page ${result.page} of ${result.totalPages}` : 'Page —'}</span><button type="button" className="admin-button admin-button-secondary" disabled={!result || page >= result.totalPages} onClick={() => setPage((current) => current + 1)}>Next</button></div></section></div>{inviteOpen ? <div className="admin-dialog-backdrop" role="presentation"><section className="admin-dialog" role="dialog" aria-modal="true" aria-labelledby="invite-title"><p className="admin-eyebrow">New vendor</p><h2 id="invite-title">Invite a vendor</h2><p>Create the invitation record now. Sending the actual email is a later integration.</p><label>Company name<input value={companyName} onChange={(event) => setCompanyName(event.target.value)} /></label><label>Email address<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} /></label><div className="admin-dialog-actions"><button type="button" className="admin-button admin-button-secondary" onClick={() => setInviteOpen(false)}>Cancel</button><button type="button" className="admin-button admin-button-primary" onClick={() => void invite()}>Record invitation</button></div></section></div> : null}</main>
}

function VendorRow({ vendor }: { vendor: AdminVendor }) {
  return <tr><td><Link href={`/admin/vendors/${vendor.id}`} className="admin-table-primary">{vendor.name}</Link><span className="admin-table-secondary">{vendor.email || 'No email'}</span></td><td><span className={`admin-status admin-status-${vendor.status}`}>{label(vendor.status)}</span></td><td>{label(vendor.onboardingStatus || 'not started')}</td><td>{vendor.productsCount ?? '—'}</td><td>{formatDate(vendor.updatedAt)}</td><td><Link href={`/admin/vendors/${vendor.id}`} className="admin-text-link">View</Link></td></tr>
}
